insert into public.profile (id, name, greeting, build_label, roles, status, available, lead, about, facts, languages, location, email, whatsapp, phone_display, linkedin_url, github_url, photo_url, cv_url, contact_title, contact_sub, seo_title, seo_description, seo_keywords) values (1, '{"en":"Mohammed Nasser Mijo","ar":"محمد ناصر ميجو","id":"Mohammed Nasser Mijo"}'::jsonb, '{"en":"Hi, I''m Mohammed.","ar":"مرحبًا، أنا محمد.","id":"Halo, saya Mohammed."}'::jsonb, '{"en":"I build","ar":"أبني","id":"Saya membangun"}'::jsonb, '{"en":["on-device AI","computer vision apps","Flutter mobile apps","LLM-powered features"],"ar":["ذكاءً اصطناعيًا يعمل على الجهاز","تطبيقات رؤية حاسوبية","تطبيقات جوال بـ Flutter","ميزات بالنماذج اللغوية"],"id":["AI di perangkat","aplikasi computer vision","aplikasi mobile Flutter","fitur berbasis LLM"]}'::jsonb, '{"en":"Open to AI / ML internships","ar":"متاح لفرص التدريب في الذكاء الاصطناعي وتعلّم الآلة","id":"Terbuka untuk magang AI / ML"}'::jsonb, true, '{"en":"I''m an Information Technology student at UIN Salatiga, Indonesia, originally from Yemen. I train machine learning models and ship them inside mobile apps, and I serve as Secretary General of the Yemeni Students Union in Indonesia.","ar":"طالب تقنية معلومات في جامعة UIN سالاتيغا بإندونيسيا، من اليمن. أدرّب نماذج تعلّم الآلة وأدمجها في تطبيقات الجوال، وأشغل منصب الأمين العام لاتحاد الطلاب اليمنيين في إندونيسيا.","id":"Saya mahasiswa Teknologi Informasi di UIN Salatiga, Indonesia, berasal dari Yaman. Saya melatih model machine learning dan menerapkannya di aplikasi mobile, serta menjabat sebagai Sekretaris Jenderal Persatuan Pelajar Yaman di Indonesia."}'::jsonb, '{"en":"I''m an Information Technology student at UIN Salatiga in Central Java, Indonesia, and I come from Yemen. Most of what I build sits where AI meets mobile apps: models I train and run on the phone, and LLM features I integrate into Flutter apps.\n\nWith SignSense I took a model from dataset to phone: hand landmarks extracted with MediaPipe, a TensorFlow classifier evaluated on a held-out test set, and a TensorFlow Lite model running inside a Flutter app. With FarmGuardAI I built, on my own, an app that uses the Gemini API to help farmers spot crop and livestock problems early.\n\nAlongside my studies I serve as Secretary General of the Yemeni Students Union in Indonesia, after a year leading its media office. Next, I want to measure how my models perform with real users, and deploy AI features through APIs and cloud services.","ar":"أدرس تقنية المعلومات في جامعة UIN سالاتيغا بجاوة الوسطى في إندونيسيا، وأنا من اليمن. معظم ما أبنيه يقع حيث يلتقي الذكاء الاصطناعي بتطبيقات الجوال: نماذج أدرّبها وأشغّلها على الهاتف، وميزات تعتمد على النماذج اللغوية أدمجها في تطبيقات Flutter.\n\nفي SignSense نقلت النموذج من البيانات إلى الهاتف: استخرجت نقاط اليد باستخدام MediaPipe، ودرّبت مصنّفًا بـ TensorFlow وقيّمته على بيانات اختبار منفصلة، ثم شغّلته بصيغة TensorFlow Lite داخل تطبيق Flutter. وفي FarmGuardAI بنيت وحدي تطبيقًا يستخدم Gemini API ليساعد المزارعين على اكتشاف مشكلات المحاصيل والمواشي مبكرًا.\n\nإلى جانب دراستي أشغل منصب الأمين العام لاتحاد الطلاب اليمنيين في إندونيسيا، بعد عام في رئاسة مكتبه الإعلامي. خطوتي التالية أن أقيس أداء نماذجي مع مستخدمين حقيقيين، وأن أنشر ميزات الذكاء الاصطناعي عبر واجهات برمجية وخدمات سحابية.","id":"Saya mahasiswa Teknologi Informasi di UIN Salatiga, Jawa Tengah, Indonesia, dan saya berasal dari Yaman. Sebagian besar yang saya bangun berada di pertemuan AI dan aplikasi mobile: model yang saya latih dan jalankan di ponsel, serta fitur berbasis LLM yang saya integrasikan ke aplikasi Flutter.\n\nLewat SignSense saya membawa model dari dataset sampai ke ponsel: titik tangan diekstrak dengan MediaPipe, classifier TensorFlow dievaluasi pada data uji terpisah, lalu dijalankan sebagai TensorFlow Lite di dalam aplikasi Flutter. Lewat FarmGuardAI saya membangun sendiri aplikasi yang memakai Gemini API untuk membantu petani mendeteksi masalah tanaman dan ternak lebih awal.\n\nDi samping kuliah, saya menjabat sebagai Sekretaris Jenderal Persatuan Pelajar Yaman di Indonesia, setelah setahun memimpin kantor medianya. Langkah berikutnya: mengukur kinerja model saya bersama pengguna nyata, dan menerapkan fitur AI melalui API dan layanan cloud."}'::jsonb, '{"en":["Based in Salatiga, Central Java, Indonesia","Bachelor''s in Information Technology, UIN Salatiga (expected 2028)","Secretary General, Yemeni Students Union in Indonesia","Focus: computer vision, on-device ML and LLM apps"],"ar":["مقيم في سالاتيغا، جاوة الوسطى، إندونيسيا","بكالوريوس تقنية المعلومات، UIN سالاتيغا (التخرّج المتوقّع 2028)","الأمين العام لاتحاد الطلاب اليمنيين في إندونيسيا","التركيز: الرؤية الحاسوبية، وتعلّم الآلة على الجهاز، وتطبيقات النماذج اللغوية"],"id":["Tinggal di Salatiga, Jawa Tengah, Indonesia","S1 Teknologi Informasi, UIN Salatiga (perkiraan lulus 2028)","Sekretaris Jenderal Persatuan Pelajar Yaman di Indonesia","Fokus: computer vision, ML di perangkat, dan aplikasi LLM"]}'::jsonb, '{"en":["Arabic: native","Indonesian: advanced","English: advanced"],"ar":["العربية: اللغة الأم","الإندونيسية: متقدّم","الإنجليزية: متقدّم"],"id":["Bahasa Arab: bahasa ibu","Bahasa Indonesia: mahir","Bahasa Inggris: mahir"]}'::jsonb, '{"en":"Salatiga, Indonesia","ar":"سالاتيغا، إندونيسيا","id":"Salatiga, Indonesia"}'::jsonb, 'mmyjw48@gmail.com', '6285385122793', '+62 853-8512-2793', 'https://www.linkedin.com/in/mohammed-nasser-mijo-a654a2343/', 'https://github.com/mmyjw48-web', '/images/mohammed.webp', null, '{"en":"Building something with AI? Let''s talk.","ar":"تبني شيئًا بالذكاء الاصطناعي؟ لنتحدّث.","id":"Sedang membangun sesuatu dengan AI? Mari bicara."}'::jsonb, '{"en":"I reply in English, Arabic or Indonesian.","ar":"أردّ بالعربية أو الإنجليزية أو الإندونيسية.","id":"Saya membalas dalam bahasa Indonesia, Inggris, atau Arab."}'::jsonb, '{"en":"Mohammed Nasser Mijo · AI & mobile apps","ar":"محمد ناصر ميجو · الذكاء الاصطناعي وتطبيقات الجوال","id":"Mohammed Nasser Mijo · AI & aplikasi mobile"}'::jsonb, '{"en":"Mohammed Nasser Salem Mijo: IT student at UIN Salatiga building computer vision and LLM-powered mobile apps. Projects, experience, awards and contact.","ar":"محمد ناصر سالم ميجو: طالب تقنية معلومات في UIN سالاتيغا يبني تطبيقات جوال تعتمد على الرؤية الحاسوبية والنماذج اللغوية. المشاريع والخبرات والجوائز ووسائل التواصل.","id":"Mohammed Nasser Salem Mijo: mahasiswa TI di UIN Salatiga yang membangun aplikasi mobile berbasis computer vision dan LLM. Proyek, pengalaman, prestasi, dan kontak."}'::jsonb, '{"en":["Mohammed Nasser","Mohammed Mijo","Mohammed Nasser Salem","Mohammed Nasser Salem Mijo","Mohammed Nasser Mijo"],"ar":["محمد ناصر","محمد ميجو","محمد ناصر سالم","محمد ناصر سالم ميجو","محمد ناصر ميجو"],"id":["Mohammed Nasser","Mohammed Mijo","Mohammed Nasser Salem","Mohammed Nasser Salem Mijo","Mohammed Nasser Mijo"]}'::jsonb) on conflict (id) do nothing;
