insert into public.doors (id, style, color, kind, sort, visible, name, intro) values ('leadership', 'leadership', 'saffron', 'leadership', 40, true, '{"en":"Leadership & Media","ar":"القيادة والإعلام","id":"Kepemimpinan & Media"}'::jsonb, '{"en":"Roles and programs where I led, organized and communicated.","ar":"مناصب وبرامج قُدت فيها ونظّمت وتواصلت.","id":"Peran dan program tempat saya memimpin, mengorganisasi, dan berkomunikasi."}'::jsonb) on conflict (id) do nothing;
insert into public.projects (visible, published, in_story, story_text, id, slug, sort, featured, doors, status, visual, title, tagline, summary, body, contribution, team, award, start_date, end_date, date_precision, stack, metrics, repo_url, demo_url, cover_url, gallery) values (true, true, true, '{"en":"Built SignSense: a TensorFlow Lite model inside a Flutter app","ar":"بنيت SignSense: نموذج TensorFlow Lite داخل تطبيق Flutter","id":"Membangun SignSense: model TensorFlow Lite di dalam aplikasi Flutter"}'::jsonb, '00000000-0000-4000-8000-000000000101', 'signsense', 10, true, array['ai', 'mobile']::text[], 'completed', 'hand', '{"en":"SignSense","ar":"SignSense","id":"SignSense"}'::jsonb, '{"en":"ASL alphabet recognition with on-device AI","ar":"التعرّف على أبجدية لغة الإشارة الأمريكية بذكاء اصطناعي يعمل على الجهاز","id":"Pengenalan alfabet ASL dengan AI di perangkat"}'::jsonb, '{"en":"Learners practice ASL letters and get instant feedback from the camera or a photo. MediaPipe extracts 21 hand landmarks, and a neural network I trained classifies them into 28 classes, running offline as TensorFlow Lite with a confidence score.","ar":"يتدرّب المتعلّم على حروف لغة الإشارة الأمريكية ويحصل على تقييم فوري من الكاميرا أو من صورة. يستخرج MediaPipe 21 نقطة من اليد، ثم تصنّفها شبكة عصبية درّبتها إلى 28 فئة، وتعمل دون إنترنت بصيغة TensorFlow Lite مع نسبة ثقة لكل توقّع.","id":"Pengguna berlatih huruf ASL dan langsung mendapat umpan balik dari kamera atau foto. MediaPipe mengekstrak 21 titik tangan, lalu jaringan saraf yang saya latih mengklasifikasikannya ke 28 kelas, berjalan offline sebagai TensorFlow Lite dengan skor keyakinan."}'::jsonb, '{"en":"Practicing sign language alone is hard, because nobody tells you whether a sign is right. SignSense is a Flutter app with an A–Z learning section and a recognition screen that works with the camera or an uploaded photo.\n\nInstead of classifying the whole image, the app first finds 21 hand landmarks with MediaPipe, turns them into 63 numbers (x, y, z for each point), normalizes them relative to the wrist, and passes them to a small neural network that runs on the phone as TensorFlow Lite. That keeps the model tiny, fast and usable offline.","ar":"التدرّب على لغة الإشارة وحدك صعب، لأن لا أحد يخبرك إن كانت الإشارة صحيحة. SignSense تطبيق Flutter فيه قسم لتعلّم الحروف من A إلى Z، وشاشة للتعرّف على الإشارة من الكاميرا أو من صورة مرفوعة.\n\nبدل تصنيف الصورة كاملة، يحدّد التطبيق أولًا 21 نقطة على اليد باستخدام MediaPipe، ويحوّلها إلى 63 رقمًا (x وy وz لكل نقطة)، ثم يطبّعها نسبةً إلى المعصم، ويمرّرها إلى شبكة عصبية صغيرة تعمل على الهاتف بصيغة TensorFlow Lite. بهذا يبقى النموذج صغيرًا وسريعًا ويعمل دون إنترنت.","id":"Berlatih bahasa isyarat sendirian itu sulit, karena tidak ada yang memberi tahu apakah isyarat Anda benar. SignSense adalah aplikasi Flutter dengan bagian belajar A–Z dan layar pengenalan yang bekerja dengan kamera atau foto yang diunggah.\n\nAlih-alih mengklasifikasikan seluruh gambar, aplikasi ini terlebih dahulu menemukan 21 titik tangan dengan MediaPipe, mengubahnya menjadi 63 angka (x, y, z untuk setiap titik), menormalkannya terhadap pergelangan tangan, lalu meneruskannya ke jaringan saraf kecil yang berjalan di ponsel sebagai TensorFlow Lite. Hasilnya model kecil, cepat, dan bisa dipakai offline."}'::jsonb, '{"en":["Extracted hand landmarks from the Kaggle ASL Alphabet dataset with MediaPipe and built a 12,496-sample feature set across 28 classes","Trained a TensorFlow/Keras network with class weights, early stopping and a stratified 70/15/15 split: 99.5% accuracy on 1,875 held-out test samples","Converted the model to a 235 KB TensorFlow Lite file, checked it before export, and integrated it with tflite_flutter","Connected MediaPipe on Android to Flutter through a Kotlin MethodChannel, with a hand-skeleton overlay and confidence scores"],"ar":["استخرجت نقاط اليد من مجموعة بيانات ASL Alphabet في Kaggle باستخدام MediaPipe، وبنيت 12,496 عيّنة موزّعة على 28 فئة","درّبت شبكة TensorFlow/Keras مع أوزان للفئات وإيقاف مبكر وتقسيم 70/15/15 متوازن: دقة 99.5% على 1,875 عيّنة اختبار منفصلة","حوّلت النموذج إلى ملف TensorFlow Lite بحجم 235 KB، وتحقّقت منه قبل التصدير، ودمجته عبر tflite_flutter","ربطت MediaPipe على أندرويد بتطبيق Flutter عبر Kotlin MethodChannel، مع رسم هيكل اليد ونسبة الثقة"],"id":["Mengekstrak titik tangan dari dataset Kaggle ASL Alphabet dengan MediaPipe dan membangun 12.496 sampel fitur di 28 kelas","Melatih jaringan TensorFlow/Keras dengan class weight, early stopping, dan pembagian 70/15/15 terstratifikasi: akurasi 99,5% pada 1.875 sampel uji terpisah","Mengonversi model menjadi file TensorFlow Lite 235 KB, mengujinya sebelum ekspor, dan mengintegrasikannya dengan tflite_flutter","Menghubungkan MediaPipe di Android ke Flutter melalui Kotlin MethodChannel, dengan overlay kerangka tangan dan skor keyakinan"]}'::jsonb, null, null, '2026-05-01', '2026-06-01', 'month', array['Python', 'TensorFlow / Keras', 'TensorFlow Lite', 'MediaPipe', 'scikit-learn', 'pandas', 'Flutter', 'Riverpod', 'Kotlin']::text[], '[{"value":{"en":"99.5%","ar":"99.5%","id":"99,5%"},"label":{"en":"test accuracy","ar":"دقة الاختبار","id":"akurasi uji"}},{"value":{"en":"28","ar":"28","id":"28"},"label":{"en":"classes (A–Z, space, delete)","ar":"فئة (A–Z، مسافة، حذف)","id":"kelas (A–Z, spasi, hapus)"}},{"value":{"en":"12,496","ar":"12,496","id":"12.496"},"label":{"en":"training samples","ar":"عيّنة تدريب","id":"sampel pelatihan"}},{"value":{"en":"235 KB","ar":"235 KB","id":"235 KB"},"label":{"en":"TensorFlow Lite model","ar":"حجم نموذج TensorFlow Lite","id":"model TensorFlow Lite"}}]'::jsonb, 'https://github.com/mmyjw48-web/sign-language-app', null, null, '{}'::text[]) on conflict (id) do nothing;
insert into public.projects (visible, published, in_story, story_text, id, slug, sort, featured, doors, status, visual, title, tagline, summary, body, contribution, team, award, start_date, end_date, date_precision, stack, metrics, repo_url, demo_url, cover_url, gallery) values (true, true, true, '{"en":"Built FarmGuardAI on my own with the Gemini API","ar":"بنيت FarmGuardAI وحدي باستخدام Gemini API","id":"Membangun FarmGuardAI sendiri dengan Gemini API"}'::jsonb, '00000000-0000-4000-8000-000000000102', 'farmguardai', 20, false, array['ai', 'mobile']::text[], 'prototype', 'auto', '{"en":"FarmGuardAI","ar":"FarmGuardAI","id":"FarmGuardAI"}'::jsonb, '{"en":"AI assistant for crop and livestock health","ar":"مساعد ذكي لصحة المحاصيل والمواشي","id":"Asisten AI untuk kesehatan tanaman dan ternak"}'::jsonb, '{"en":"Detects plant diseases from leaf photos, suggests possible livestock diagnoses from the animal''s type, age and how long it has been sick, and recommends treatment or a vet visit. The MVP uses the Gemini API; the next step is models trained on labeled agricultural data.","ar":"يكتشف أمراض النباتات من صور الأوراق، ويقترح تشخيصات محتملة للمواشي بناءً على نوع الحيوان وعمره ومدة مرضه، ويوصي بالعلاج أو بزيارة الطبيب البيطري. تعتمد النسخة الأولى على Gemini API، والخطوة التالية نماذج مدرّبة على بيانات زراعية مصنّفة.","id":"Mendeteksi penyakit tanaman dari foto daun, menyarankan kemungkinan diagnosis ternak berdasarkan jenis, umur, dan lama sakit hewan, serta merekomendasikan pengobatan atau kunjungan ke dokter hewan. MVP ini memakai Gemini API; langkah berikutnya adalah model yang dilatih dengan data pertanian berlabel."}'::jsonb, '{"en":"Crop and livestock diseases are often spotted late, and many farmers have little access to agricultural or veterinary experts. FarmGuardAI puts a first opinion in their pocket. The project is built around SDG 2 (Zero Hunger).\n\nThis version uses the Gemini API to validate the idea and the workflow quickly. The plan is to replace it with dedicated models trained on real, labeled agricultural data.","ar":"كثيرًا ما تُكتشف أمراض المحاصيل والمواشي متأخرة، ولا يصل كثير من المزارعين إلى خبراء زراعيين أو أطباء بيطريين. يضع FarmGuardAI رأيًا أوليًا في جيب المزارع، وهو مبني حول الهدف الثاني من أهداف التنمية المستدامة (القضاء على الجوع).\n\nتستخدم هذه النسخة Gemini API للتحقق من الفكرة وسير العمل بسرعة، والخطة استبداله بنماذج مخصّصة مدرّبة على بيانات زراعية حقيقية ومصنّفة.","id":"Penyakit tanaman dan ternak sering terdeteksi terlambat, dan banyak petani sulit menjangkau ahli pertanian atau dokter hewan. FarmGuardAI memberi pendapat awal langsung di saku mereka. Proyek ini dibangun di sekitar SDG 2 (Tanpa Kelaparan).\n\nVersi ini memakai Gemini API untuk menguji ide dan alur kerja dengan cepat. Rencananya, Gemini akan diganti dengan model khusus yang dilatih pada data pertanian nyata dan berlabel."}'::jsonb, '{"en":["Built the whole app on my own in Flutter, with Riverpod and GoRouter","Plant disease detection from leaf photos, and livestock diagnosis from the animal''s type, age and illness duration, with risk levels and next steps","An AI chat assistant for farming questions, powered by the Gemini API","Firebase Authentication and Cloud Firestore for accounts and data"],"ar":["بنيت التطبيق كاملًا وحدي بـ Flutter مع Riverpod وGoRouter","كشف أمراض النبات من صور الأوراق، وتشخيص المواشي حسب نوع الحيوان وعمره ومدة مرضه، مع مستوى الخطورة والخطوات التالية","مساعد محادثة ذكي للأسئلة الزراعية يعمل بـ Gemini API","Firebase Authentication وCloud Firestore للحسابات والبيانات"],"id":["Membangun seluruh aplikasi sendiri dengan Flutter, Riverpod, dan GoRouter","Deteksi penyakit tanaman dari foto daun, dan diagnosis ternak berdasarkan jenis, umur, dan lama sakit, lengkap dengan tingkat risiko dan langkah berikutnya","Asisten chat AI untuk pertanyaan pertanian, ditenagai Gemini API","Firebase Authentication dan Cloud Firestore untuk akun dan data"]}'::jsonb, '{"en":"Solo","ar":"فردي","id":"Mandiri"}'::jsonb, null, '2026-06-01', '2026-07-01', 'month', array['Flutter', 'Dart', 'Gemini API', 'Firebase', 'SQLite', 'Riverpod', 'GoRouter']::text[], '[]'::jsonb, 'https://github.com/mmyjw48-web/FarmGuardAI', null, '/images/projects/farmguardai-showcase.webp', '{}'::text[]) on conflict (id) do nothing;
insert into public.projects (visible, published, in_story, story_text, id, slug, sort, featured, doors, status, visual, title, tagline, summary, body, contribution, team, award, start_date, end_date, date_precision, stack, metrics, repo_url, demo_url, cover_url, gallery) values (true, true, false, null, '00000000-0000-4000-8000-000000000103', 'skillbridge-oman', 30, false, array['ai']::text[], 'hackathon', 'auto', '{"en":"SkillBridge Oman","ar":"SkillBridge Oman","id":"SkillBridge Oman"}'::jsonb, '{"en":"Evidence-based skill matching for junior tech roles","ar":"مطابقة المهارات بالأدلة لوظائف التقنية للمبتدئين","id":"Pencocokan kompetensi berbasis bukti untuk posisi teknologi junior"}'::jsonb, '{"en":"Compares an English CV with a real junior job description and weighs the evidence for each skill: demonstrated, claimed, not enough evidence, or missing, instead of only matching keywords.","ar":"يقارن سيرة ذاتية بالإنجليزية بوصف وظيفة حقيقية للمبتدئين، ويزن الأدلة على كل مهارة: مثبتة، أو مُدّعاة، أو بلا أدلة كافية، أو غائبة، بدل الاكتفاء بمطابقة الكلمات المفتاحية.","id":"Membandingkan CV berbahasa Inggris dengan deskripsi pekerjaan junior yang nyata dan menimbang bukti setiap keterampilan: terbukti, diklaim, bukti kurang, atau tidak ada, bukan sekadar mencocokkan kata kunci."}'::jsonb, '{"en":"A candidate-facing MVP built for a hackathon. It reads an English CV next to a real junior technology job description and sorts every competency by the strength of its evidence.","ar":"نموذج أولي موجّه للمتقدّمين للوظائف، بُني في هاكاثون. يقرأ سيرة ذاتية بالإنجليزية إلى جانب وصف وظيفة تقنية حقيقية للمبتدئين، ويصنّف كل مهارة حسب قوة الأدلة عليها.","id":"MVP untuk pencari kerja yang dibuat dalam hackathon. Aplikasi ini membaca CV berbahasa Inggris berdampingan dengan deskripsi pekerjaan teknologi junior yang nyata, lalu mengelompokkan setiap kompetensi berdasarkan kekuatan buktinya."}'::jsonb, '{"en":[],"ar":[],"id":[]}'::jsonb, '{"en":"Team","ar":"فريق","id":"Tim"}'::jsonb, null, null, null, 'month', '{}'::text[], '[]'::jsonb, null, null, '/images/projects/skillbridge.webp', '{}'::text[]) on conflict (id) do nothing;
insert into public.projects (visible, published, in_story, story_text, id, slug, sort, featured, doors, status, visual, title, tagline, summary, body, contribution, team, award, start_date, end_date, date_precision, stack, metrics, repo_url, demo_url, cover_url, gallery) values (true, true, false, null, '00000000-0000-4000-8000-000000000104', 'smart-student-uin-salatiga', 40, false, array['mobile']::text[], 'prototype', 'phone', '{"en":"Smart Student UIN Salatiga","ar":"Smart Student UIN Salatiga","id":"Smart Student UIN Salatiga"}'::jsonb, '{"en":"Digital services app for UIN Salatiga students","ar":"تطبيق خدمات رقمية لطلاب UIN سالاتيغا","id":"Aplikasi layanan digital untuk mahasiswa UIN Salatiga"}'::jsonb, '{"en":"A team prototype of a university services app. My part: reminders, KRS document handling with email delivery, GPA history, Arabic-language support, navigation improvements and testing.","ar":"نموذج أولي لتطبيق خدمات جامعية بنيناه كفريق. الجزء الذي نفّذته: التذكيرات، ومعالجة مستندات KRS وإرسالها بالبريد، وسجل المعدّل، ودعم اللغة العربية، وتحسين التنقّل، والاختبار.","id":"Prototipe tim untuk aplikasi layanan kampus. Bagian saya: pengingat, pengelolaan dokumen KRS dengan pengiriman email, riwayat IPK, dukungan bahasa Arab, perbaikan navigasi, dan pengujian."}'::jsonb, '{"en":"","ar":"","id":""}'::jsonb, '{"en":["Reminders","KRS document handling with email delivery","GPA history","Arabic-language support","Navigation improvements and testing"],"ar":["التذكيرات","معالجة مستندات KRS وإرسالها بالبريد","سجل المعدّل","دعم اللغة العربية","تحسين التنقّل والاختبار"],"id":["Pengingat","Pengelolaan dokumen KRS dengan pengiriman email","Riwayat IPK","Dukungan bahasa Arab","Perbaikan navigasi dan pengujian"]}'::jsonb, '{"en":"Team","ar":"فريق","id":"Tim"}'::jsonb, null, '2026-04-01', '2026-06-01', 'month', array['Flutter', 'Dart']::text[], '[]'::jsonb, 'https://github.com/mmyjw48-web/Smart-Student-UIN-Salatiga', null, '/images/projects/smart-student-home.webp', array['/images/projects/smart-student-team.webp', '/images/projects/smart-student-gpa-history.webp']::text[]) on conflict (id) do nothing;
insert into public.projects (visible, published, in_story, story_text, id, slug, sort, featured, doors, status, visual, title, tagline, summary, body, contribution, team, award, start_date, end_date, date_precision, stack, metrics, repo_url, demo_url, cover_url, gallery) values (true, true, false, null, '00000000-0000-4000-8000-000000000105', 'layananku', 50, false, array['mobile']::text[], 'concept', 'auto', '{"en":"LayananKu","ar":"LayananKu","id":"LayananKu"}'::jsonb, '{"en":"One app for Indonesian public services","ar":"تطبيق واحد للخدمات الحكومية في إندونيسيا","id":"Satu aplikasi untuk layanan publik Indonesia"}'::jsonb, '{"en":"A product concept and Flutter prototype that brings several public-service areas into one role-based mobile experience, planned as a bilingual, Android-first app.","ar":"فكرة منتج ونموذج أولي بـ Flutter يجمع عدة مجالات للخدمات العامة في تجربة جوال واحدة حسب دور المستخدم، ومخطط له أن يكون ثنائي اللغة ويبدأ بأندرويد.","id":"Konsep produk dan prototipe Flutter yang menyatukan beberapa layanan publik dalam satu pengalaman mobile berbasis peran, direncanakan dua bahasa dan Android-first."}'::jsonb, '{"en":"","ar":"","id":""}'::jsonb, '{"en":[],"ar":[],"id":[]}'::jsonb, null, null, null, null, 'month', array['Flutter']::text[], '[]'::jsonb, null, null, '/images/projects/layananku.webp', '{}'::text[]) on conflict (id) do nothing;
insert into public.projects (visible, published, in_story, story_text, id, slug, sort, featured, doors, status, visual, title, tagline, summary, body, contribution, team, award, start_date, end_date, date_precision, stack, metrics, repo_url, demo_url, cover_url, gallery) values (true, true, false, null, '00000000-0000-4000-8000-000000000106', 'lestari-tani', 60, false, array['web']::text[], 'completed', 'auto', '{"en":"Lestari Tani","ar":"Lestari Tani","id":"Lestari Tani"}'::jsonb, '{"en":"Plastic-free store for local products","ar":"متجر إلكتروني لمنتجات محلية بلا بلاستيك","id":"Toko daring produk lokal tanpa plastik"}'::jsonb, '{"en":"An online store that sells local products without plastic packaging, to protect the environment and support local producers. Won 3rd place in Web Development at INTECHFEST 2026, UIN Salatiga.","ar":"متجر إلكتروني يبيع المنتجات المحلية دون تغليف بلاستيكي، ليحمي البيئة ويدعم المنتجين المحليين. حصل على المركز الثالث في فئة تطوير الويب في INTECHFEST 2026 بجامعة UIN سالاتيغا.","id":"Toko daring yang menjual produk lokal tanpa kemasan plastik untuk menjaga lingkungan dan mendukung produsen lokal. Meraih Juara 3 Web Development di INTECHFEST 2026, UIN Salatiga."}'::jsonb, '{"en":"","ar":"","id":""}'::jsonb, '{"en":[],"ar":[],"id":[]}'::jsonb, '{"en":"With Ibrahim Hassan","ar":"مع إبراهيم حسن","id":"Bersama Ibrahim Hassan"}'::jsonb, '{"en":"3rd place · INTECHFEST 2026","ar":"المركز الثالث · INTECHFEST 2026","id":"Juara 3 · INTECHFEST 2026"}'::jsonb, '2026-01-01', null, 'year', '{}'::text[], '[]'::jsonb, null, null, null, '{}'::text[]) on conflict (id) do nothing;
