insert into public.experiences (visible, published, in_story, story_text, id, sort, in_door, title, org, employment_type, location, start_date, end_date, is_current, date_precision, summary, bullets, link) values (true, true, true, '{"en":"Became Secretary General of the Yemeni Students Union in Indonesia","ar":"أصبحت الأمين العام لاتحاد الطلاب اليمنيين في إندونيسيا","id":"Menjadi Sekretaris Jenderal Persatuan Pelajar Yaman di Indonesia"}'::jsonb, '00000000-0000-4000-8000-000000000201', 10, true, '{"en":"Secretary General, 5th term","ar":"الأمين العام، الدورة الخامسة","id":"Sekretaris Jenderal, periode ke-5"}'::jsonb, '{"en":"Yemeni Students Union in Indonesia","ar":"اتحاد الطلاب اليمنيين في إندونيسيا","id":"Persatuan Pelajar Yaman di Indonesia"}'::jsonb, '{"en":"Part-time · Remote","ar":"دوام جزئي · عن بُعد","id":"Paruh waktu · Jarak jauh"}'::jsonb, '{"en":"Indonesia","ar":"إندونيسيا","id":"Indonesia"}'::jsonb, '2026-05-01', '2027-05-01', true, 'month', '{"en":"Responsible for the union''s executive administration for the 2026–2027 term.","ar":"مسؤول عن الإدارة التنفيذية للاتحاد في دورة 2026–2027.","id":"Bertanggung jawab atas administrasi eksekutif persatuan untuk periode 2026–2027."}'::jsonb, '{"en":["Coordinate union meetings, agendas, official letters and activity reports","Manage communication between committees and follow up on assigned tasks","Support student programs, new-student reception and organizational activities","Support external relations with universities and international offices"],"ar":["تنسيق اجتماعات الاتحاد وجداول الأعمال والمراسلات الرسمية وتقارير الأنشطة","إدارة التواصل بين اللجان ومتابعة المهام المكلّفة","دعم البرامج الطلابية واستقبال الطلاب الجدد والأنشطة التنظيمية","دعم العلاقات الخارجية مع الجامعات والمكاتب الدولية"],"id":["Mengoordinasikan rapat, agenda, surat resmi, dan laporan kegiatan persatuan","Mengelola komunikasi antarkomite dan menindaklanjuti tugas","Mendukung program mahasiswa, penyambutan mahasiswa baru, dan kegiatan organisasi","Mendukung hubungan eksternal dengan universitas dan kantor internasional"]}'::jsonb, null) on conflict (id) do nothing;
insert into public.experiences (visible, published, in_story, story_text, id, sort, in_door, title, org, employment_type, location, start_date, end_date, is_current, date_precision, summary, bullets, link) values (true, true, true, '{"en":"Head of Media Office, Yemeni Students Union in Indonesia","ar":"رئيس المكتب الإعلامي في اتحاد الطلاب اليمنيين في إندونيسيا","id":"Kepala Kantor Media, Persatuan Pelajar Yaman di Indonesia"}'::jsonb, '00000000-0000-4000-8000-000000000202', 20, true, '{"en":"Head of Media Office","ar":"رئيس المكتب الإعلامي","id":"Kepala Kantor Media"}'::jsonb, '{"en":"Yemeni Students Union in Indonesia","ar":"اتحاد الطلاب اليمنيين في إندونيسيا","id":"Persatuan Pelajar Yaman di Indonesia"}'::jsonb, '{"en":"Part-time · Remote","ar":"دوام جزئي · عن بُعد","id":"Paruh waktu · Jarak jauh"}'::jsonb, '{"en":"Indonesia","ar":"إندونيسيا","id":"Indonesia"}'::jsonb, '2025-05-01', '2026-05-01', false, 'month', '{"en":"Led the union''s media and online communication for one year.","ar":"قدت العمل الإعلامي والتواصل الرقمي للاتحاد لمدة عام.","id":"Memimpin media dan komunikasi daring persatuan selama satu tahun."}'::jsonb, '{"en":["Led video production, graphic design, social media management, website development and content editing","Supervised coverage and publication of the union''s activities, events and official announcements","Managed online communication and helped improve the union''s digital presence"],"ar":["قدت إنتاج الفيديو والتصميم الجرافيكي وإدارة وسائل التواصل وتطوير الموقع وتحرير المحتوى","أشرفت على تغطية أنشطة الاتحاد وفعالياته وإعلاناته الرسمية ونشرها","أدرت التواصل الرقمي وساهمت في تحسين حضور الاتحاد على الإنترنت"],"id":["Memimpin produksi video, desain grafis, pengelolaan media sosial, pengembangan situs web, dan penyuntingan konten","Mengawasi liputan dan publikasi kegiatan, acara, serta pengumuman resmi persatuan","Mengelola komunikasi daring dan membantu meningkatkan kehadiran digital persatuan"]}'::jsonb, null) on conflict (id) do nothing;
